insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-00000000000f', 'en', null, 'Public Speaking', 'A practical, confidence-first tour of speaking to an audience — from taming nerves to structuring, delivering, and persuading. Structure adapted from OpenStax Communication (CC BY 4.0).', null, 'work', 15, true, 'science', '{}')
