insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000000f', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The most reliable cure for speaking nerves before a talk is…","options":["avoiding eye contact","preparation and rehearsal","reading every word off a slide","speaking as fast as possible"],"answer":1,"explanation":"Nerves shrink when you know your material cold — see ''Overcoming speaking anxiety''."},{"prompt":"Audience analysis mainly helps you decide…","options":["what to wear","what your audience already knows and cares about","how long the room is","which font to use"],"answer":1,"explanation":"You tailor content to the listeners'' knowledge and needs — see ''Audience analysis''."},{"prompt":"A classic speech has three main parts:","options":["slides, notes, questions","introduction, body, conclusion","hook, joke, apology","title, credits, exit"],"answer":1,"explanation":"Intro, body, conclusion — see ''Structuring a speech''."},{"prompt":"A thesis statement is…","options":["a list of every fact you know","the one sentence that captures your central message","the title slide","a closing thank-you"],"answer":1,"explanation":"One clear controlling idea — see ''Structuring a speech''."},{"prompt":"Which is a delivery skill rather than a content skill?","options":["choosing a topic","pausing for emphasis","writing a thesis","researching sources"],"answer":1,"explanation":"Pausing is about how you deliver — see ''Delivery''."},{"prompt":"The ''general purpose'' of a speech is usually to…","options":["fill time","inform, persuade, or entertain","test the microphone","read the slides aloud"],"answer":1,"explanation":"Purpose drives every choice — see ''Audience analysis and purpose''."},{"prompt":"A good visual aid should…","options":["contain your full script","support a point, not replace you","have as much text as possible","be read word for word"],"answer":1,"explanation":"Slides support the speaker — see ''Delivery''."},{"prompt":"Persuasion is strongest when it combines…","options":["only statistics","logic, credibility, and emotion","only volume","only slides"],"answer":1,"explanation":"Logos, ethos, pathos together — see ''Persuasion and storytelling''."}]}'::jsonb, null, 10),
  (2, 'Overcoming speaking anxiety', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why public speaking triggers anxiety and use three concrete techniques to steady yourself. Warm-up: think of the last time you felt nervous before speaking — what did your body actually do?"},{"heading":"The idea","text":"That racing heart is your nervous system treating a speech like a threat. This is normal and even useful: the same adrenaline that feels like fear also sharpens focus. The trick is *reframing* it as readiness, not danger. Three techniques do most of the work: over-*prepare* so your material is automatic, *rehearse aloud* (not just in your head) so your mouth knows the words, and use slow *diaphragmatic breathing* to lower your heart rate before you start. Example: a speaker who practices a talk five times out loud stops fearing a blank mind, because the opening lines come without thinking."},{"heading":"Worked example","text":"Weak self-talk: ''Everyone will see me shake and think I''m incompetent.'' Rework it: ''My hands might buzz for the first minute; that fades once I''m into my second point, and the audience wants me to succeed.'' The first version predicts disaster and freezes you; the second names the feeling, time-boxes it, and reminds you the room is on your side. Notice how a strong reframe is specific and forward-looking, not just ''stay calm.''"},{"heading":"Your turn","text":"Reframe each anxious thought into a calmer, realistic one: (1) ''I''ll forget everything.'' (2) ''My voice will crack and it''ll be ruined.'' (3) ''They can tell I''m terrified.'' Answers (samples): (1) ''If I lose my place, I''ll glance at my note card and keep going — a pause is fine.'' (2) ''If my voice wavers, I''ll take a breath and slow down; one shaky word isn''t the whole talk.'' (3) ''People rarely notice nerves I feel inside; I''ll focus on my message, not on being watched.''"},{"heading":"Common mistakes & exit ticket","text":"Mistake: memorizing every word — one slip then derails you; learn the *structure* instead. Mistake: rehearsing silently, which hides the hard parts. Mistake: trying to feel zero nerves. Exit: (a) Name one technique that lowers heart rate on the spot. (b) Should you rehearse in your head or out loud? Answers: slow diaphragmatic breathing; out loud."}]}'::jsonb, 'Nerves are energy — the goal is to channel them, not erase them.', 12),
  (3, 'Audience analysis and purpose', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Analyze an audience and state a clear general and specific purpose for a talk. Warm-up: would you explain the same idea the same way to a room of experts and a room of total beginners? Why not?"},{"heading":"The idea","text":"Every speech is aimed at *this* audience, not a generic one. Audience analysis means asking what listeners already know, what they care about, and what they need from you. From that you set a *general purpose* — usually to inform, to persuade, or to entertain — and a sharper *specific purpose*, a single sentence naming exactly what you want listeners to know, believe, or do. Example: general purpose ''to persuade''; specific purpose ''to convince my classmates to back up their files weekly.'' The clearer the target, the easier every later choice becomes."},{"heading":"Worked example","text":"A vague aim: ''I want to talk about money.'' Rework it for a student audience: general purpose ''to inform''; specific purpose ''to help first-year students set up a simple monthly budget in three steps.'' Notice the upgrade: we named the listeners (first-year students), the outcome (set up a budget), and the scope (three steps). A weak purpose tells you nothing about what to cut; a strong one makes half your outline decisions for you."},{"heading":"Your turn","text":"For each, write a specific purpose sentence naming audience + outcome: (1) topic ''recycling'', audience your co-workers; (2) topic ''a hobby you love'', audience strangers at a meetup; (3) topic ''a workplace policy'', audience your manager. Answers (samples): (1) ''To persuade my co-workers to sort recyclables using the new three-bin system.'' (2) ''To inform meetup guests how to start rock climbing safely on a budget.'' (3) ''To persuade my manager to approve one work-from-home day per week.''"},{"heading":"Common mistakes & exit ticket","text":"Mistake: writing a topic (''social media'') and calling it a purpose — a purpose states an outcome. Mistake: ignoring what the audience already knows and either boring or losing them. Exit: (a) Name the three common general purposes. (b) A specific purpose should name the audience and what?  Answers: inform, persuade, entertain; the outcome (what they''ll know, believe, or do)."}]}'::jsonb, 'First ask ''who is listening and why'', then decide what to say.', 12),
  (4, 'Structuring a speech: intro, body, conclusion', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Build the three-part skeleton of a speech and write a one-sentence thesis. Warm-up: from the last talk you heard, can you recall its main point in one sentence? If not, the structure probably failed."},{"heading":"The idea","text":"Structure is what lets listeners follow you without a rewind button. The *introduction* grabs attention, states your *thesis* (the single controlling idea), and previews your main points. The *body* develops two to four main points in a logical order, each with support (a fact, an example, a story). The *conclusion* signals the end, restates the thesis, and leaves a memorable final thought. A thesis is the spine: ''Weekly backups protect you from losing irreplaceable work'' tells the audience — and you — exactly what everything else must serve."},{"heading":"Worked example","text":"Weak opening: ''Um, today I guess I''ll talk a bit about time management, there''s a lot to say.'' Rework it into a strong opening: ''Last week I nearly missed a deadline that mattered — until one simple habit saved me. In the next five minutes I''ll show you the three-step method so it never happens to you.'' The strong version hooks with a concrete moment, implies the thesis (a three-step method prevents missed deadlines), and previews the structure. A weak opening apologizes and wanders; a strong one promises value and signals a map."},{"heading":"Your turn","text":"For a talk on ''staying hydrated at work'', draft: (1) a one-sentence thesis, (2) two or three main points for the body, (3) a one-line closing thought. Answers (samples): (1) Thesis: ''Drinking water on a schedule keeps your energy and focus steady all afternoon.'' (2) Points: how dehydration drains focus; a simple bottle-per-block routine; easy reminders that make it stick. (3) Close: ''Fill your bottle before your next meeting — your 3 p.m. self will thank you.''"},{"heading":"Common mistakes & exit ticket","text":"Mistake: opening with ''Sorry, I didn''t prepare much'' — you just told the audience to tune out. Mistake: cramming eight main points nobody can hold. Mistake: no thesis, so the talk lists facts with no spine. Exit: (a) Name the three main parts in order. (b) How many main points is a safe range for a short talk? Answers: introduction, body, conclusion; two to four."}]}'::jsonb, 'Tell them what you''ll say, say it, then tell them what you said.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The best on-the-spot way to lower a racing heart before speaking is…","options":["talking faster","slow diaphragmatic breathing","skipping your notes","avoiding the audience''s eyes"],"answer":1,"explanation":"Slow breathing calms the body''s alarm response."},{"prompt":"You should rehearse a speech…","options":["silently in your head","out loud, more than once","only the night before","by rereading your slides"],"answer":1,"explanation":"Speaking aloud trains your mouth and exposes hard parts."},{"prompt":"A ''specific purpose'' names the audience and…","options":["the room size","the outcome you want","the font","the time limit"],"answer":1,"explanation":"It states what listeners should know, believe, or do."},{"prompt":"Which is a general purpose of a speech?","options":["to persuade","to use slides","to stand still","to finish early"],"answer":0,"explanation":"Inform, persuade, and entertain are the general purposes."},{"prompt":"The thesis of a speech is…","options":["the closing thank-you","its single controlling idea","a list of sources","the title slide"],"answer":1,"explanation":"One sentence capturing the central message."},{"prompt":"A strong opening should…","options":["apologize for weak prep","hook attention and preview the structure","list every point in detail","read the first slide aloud"],"answer":1,"explanation":"Grab attention, state the thesis, preview the points."}]}'::jsonb, null, 8),
  (6, 'Delivery: voice, body language, and visual aids', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Use voice, body, and visuals to reinforce your message instead of fighting it. Warm-up: picture a speaker who reads every word off a crowded slide in a flat voice — what makes it hard to watch?"},{"heading":"The idea","text":"Delivery is everything the audience sees and hears beyond the words. *Voice*: vary pace and volume, and use the *pause* — a deliberate silence after a key line lands harder than any emphasis. *Body language*: stand grounded, keep open gestures, and make real eye contact with individuals, not the back wall. *Visual aids*: a good slide supports one idea with an image or a few words; it never becomes your script. Example: after stating your main claim, pause for two full seconds and hold eye contact — the room leans in."},{"heading":"Worked example","text":"Weak slide-and-delivery: a slide packed with a paragraph while the speaker faces the screen and reads it monotone. Rework it: cut the slide to a single phrase plus one image, turn to face the audience, say the point in your own words, then pause. The weak version splits attention (people read *and* listen and do neither well) and hides the speaker; the strong version keeps you as the focus and uses the slide as a signpost. Rule of thumb: if the audience can get everything from the slide, they don''t need you."},{"heading":"Your turn","text":"Fix each delivery problem: (1) speaker rushes through the key point; (2) slide has 60 words of text; (3) speaker stares at their notes the whole time. Answers (samples): (1) Slow down and add a pause right after the key point so it registers. (2) Cut to a short phrase or a single image and say the rest aloud. (3) Look up and hold eye contact with one person per sentence, glancing at notes only briefly."},{"heading":"Common mistakes & exit ticket","text":"Mistake: filling silence with ''um'' instead of pausing — a clean pause reads as confidence. Mistake: turning your back to read slides. Mistake: putting your whole script on screen. Exit: (a) What simple vocal tool makes a key line land harder? (b) A slide should support the speaker or replace them? Answers: the pause; support them."}]}'::jsonb, 'How you say it can outweigh what you say — pauses are punctuation.', 13),
  (7, 'Persuasion and storytelling', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Combine credibility, logic, and emotion, and use a short story to make a point stick. Warm-up: what do you remember more clearly — a statistic you heard last month or a story a friend told you? Why?"},{"heading":"The idea","text":"Persuasion rests on three appeals: *ethos* (your credibility and trustworthiness), *logos* (logic and evidence), and *pathos* (emotion). Strong persuasion braids all three: you sound credible, you back claims with reasons, and you make the audience *feel* the stakes. Stories are the most efficient way to deliver pathos and make abstract points concrete. A tiny narrative — a person, a problem, a turn, a resolution — gives listeners something to remember long after the numbers fade. Example: ''Recycling saves resources'' is forgettable; a 30-second story about one overflowing bin that changed a whole office''s habit is not."},{"heading":"Worked example","text":"Weak persuasive point: ''You should save money because it''s responsible.'' Rework it with all three appeals plus a story: ''As someone who once faced a surprise car repair with an empty account (ethos + story), I learned that saving just $20 a week builds a $1,000 cushion in a year (logos) — enough to turn a panic into a shrug (pathos).'' The weak version asserts; the strong version earns trust, shows the math, and makes the payoff feel real. Notice the story is short and serves the point — it isn''t a detour."},{"heading":"Your turn","text":"Label the appeal each line leans on — ethos, logos, or pathos: (1) ''Studies of 2,000 commuters show carpooling cuts costs by 40%.'' (2) ''I''ve led this team for ten years, so trust me on this.'' (3) ''Imagine never missing your child''s bedtime again.'' Answers: (1) logos, (2) ethos, (3) pathos."},{"heading":"Common mistakes & exit ticket","text":"Mistake: piling on statistics with no emotion — accurate but unmoving. Mistake: all emotion with no evidence — moving but not credible. Mistake: a story so long it buries the point. Exit: (a) Which appeal is about the speaker''s credibility? (b) Name one job a short story does better than a statistic. Answers: ethos; it makes an abstract point concrete and memorable (delivers pathos)."}]}'::jsonb, 'Facts inform; stories move — persuasion needs both.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"thesis statement","translation":"the single sentence that captures a speech''s central message","example":"Every main point should support your thesis statement."},{"term":"specific purpose","translation":"a one-sentence goal naming the audience and the outcome you want","example":"My specific purpose is to persuade classmates to back up their files weekly."},{"term":"audience analysis","translation":"figuring out what listeners know, care about, and need before you speak","example":"Audience analysis stopped me from over-explaining basics to experts."},{"term":"ethos","translation":"the appeal based on the speaker''s credibility and trustworthiness","example":"Naming her ten years of experience built ethos fast."},{"term":"pathos","translation":"the appeal that reaches the audience''s emotions","example":"A short personal story is a reliable way to create pathos."},{"term":"the pause","translation":"a deliberate silence used to let a key point land","example":"She used the pause after her thesis and the room went quiet."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"A good visual aid should…","options":["contain your full script","support one idea, not replace you","hold as much text as possible","be read word for word"],"answer":1,"explanation":"Slides are signposts; you carry the message."},{"prompt":"The vocal tool that makes a key line land harder is…","options":["speaking louder throughout","the deliberate pause","talking faster","filler words like ''um''"],"answer":1,"explanation":"A clean pause gives a point room to register."},{"prompt":"''I''ve worked in nursing for fifteen years'' is an appeal to…","options":["logos","ethos","pathos","none"],"answer":1,"explanation":"It builds the speaker''s credibility (ethos)."},{"prompt":"''Imagine finally sleeping through the night'' is an appeal to…","options":["logos","ethos","pathos","structure"],"answer":2,"explanation":"It targets emotion (pathos)."},{"prompt":"A short story in a persuasive speech mainly…","options":["pads the time","makes an abstract point concrete and memorable","replaces the thesis","proves statistics wrong"],"answer":1,"explanation":"Narrative delivers emotion and sticks in memory."},{"prompt":"Strong eye contact means looking…","options":["at the back wall","at individuals in the audience","only at your notes","only at the screen"],"answer":1,"explanation":"Connect with real people, one at a time."}]}'::jsonb, null, 8),
  (10, 'Applied project: plan a 5-minute speech', 'writing', '{"sections":[{"heading":"The task","text":"Plan and outline a 5-minute speech on a topic you know. You won''t deliver it here — you''ll design it so carefully that delivery would be the easy part. Pick any topic you could speak about with a clear goal."},{"heading":"Milestones","text":"1) Write a one-sentence specific purpose naming your audience and the outcome. 2) Write a one-sentence thesis. 3) Draft a strong opening (a hook plus a preview) — no apologies. 4) Outline two to four body points, each with one piece of support (a fact, example, or short story). 5) Write a closing line that restates the thesis and leaves a final thought. 6) Note one delivery choice you''ll use (a pause, a visual, an eye-contact plan) and one technique for managing nerves."},{"heading":"Self-check rubric","text":"✔ Specific purpose names both the audience and the outcome. ✔ The thesis is a single, clear controlling idea. ✔ The opening hooks attention and previews the structure without apologizing. ✔ Each body point has real support, and at least one uses a short story. ✔ The conclusion restates the thesis and ends memorably. ✔ You named a concrete delivery choice and a nerves technique. If all six hold, your speech is ready to rehearse out loud."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000000f' and l.position = v.pos
);
